using HelalRehber.Shared;
using BlazorApp1.Services;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Http;
using System.Text.Json;
void Check(bool ok,string why){if(!ok)throw new Exception(why);}
FoodPreferences P(params string[] ids)=>new(){Allergens=ids};
FoodPreferenceResult E(string text,string language="tr",FoodPreferences? p=null)=>FoodPreferenceRules.Evaluate(p??P("milk","peanuts"),text,language);
Check(FoodPreferenceRules.All.Length==14,"Allergen groups");
Check(!E("").Summary.Contains("alerjensiz ürün")&&E("").Summary.Contains("eksik"),"Missing content safety");
var free=E("milk-free; whey powder; may contain peanuts","en");
Check(free.Findings.Any(x=>x.Context.StartsWith("İçermez"))&&free.Findings.Any(x=>x.Match.Contains("whey")&&!x.Context.StartsWith("İçermez"))&&free.Findings.Any(x=>x.Item=="Yer fıstığı"&&x.Context.StartsWith("Olası")),"Free declaration hid separate ingredient/trace");
var tr=E("SÜT içermez; peyniraltı suyu; eser miktarda yer fıstığı içerebilir");Check(tr.Findings.Any(x=>x.Match.Contains("peyniraltı"))&&tr.Findings.Any(x=>x.Context.StartsWith("Olası")),"TR normalization/trace");
Check(E("œuf et farine","fr",new(){Diet="vegan"}).Findings.Any(x=>x.Match.Contains("œuf")),"French ligature");Check(E("sucre et farine","fr",new(){Diet="vegetarian"}).Findings.Count==0,"French et treated as meat");
Check(E("milkshake, peanutsomething","en").Findings.Count==0,"Word boundaries");
var tags=FoodPreferenceRules.Evaluate(P("milk","peanuts"),"原材料は砂糖","ja",["en:milk"],["en:peanuts"]);Check(tags.Findings.Count==2&&tags.Findings.Any(x=>x.Context.Contains("eser miktar"))&&tags.Summary.Contains("desteklenmiyor"),"Canonical tags/unsupported text");
var veganTags=FoodPreferenceRules.Evaluate(new(){Diet="vegan"},"","ja",["en:milk"],[]);Check(veganTags.Findings.Any(x=>x.Item.Contains("Vegan")),"Vegan source allergen warning");
var lactose=E("lactose-free milk","en",new(){AvoidLactose=true});Check(lactose.Findings.Count>0&&lactose.Summary.Contains("laktoz miktarını belirlemez"),"Lactose vs milk protein");
Check(E("honey, egg, chicken","en",new(){Diet="vegan"}).Findings.Count>=3,"Vegan ingredients");
Check(E("rice, water","en",new(){Diet="vegan"}).Summary.Contains("güvenli/alerjensiz/uygun sonucu verilmedi"),"No match safety");
Check(E("wheat flour","en",new(){AvoidGluten=true}).Findings.Count>0,"Gluten avoidance");
Check(E("КИВИ, вода","ru",new(){Custom="киви"}).Findings.Count==1,"Unicode custom exact match");
Check(FoodPreferenceRules.Validate(new(){Custom=string.Join(',',Enumerable.Repeat("test",9))}).Count>0,"Custom count limit");
Check(FoodPreferenceRules.Validate(P("unknown")).Count>0,"Unknown allergen ID");Check(FoodPreferenceRules.Read("bad-json").Active==false,"Corrupt stored preferences");
var many=E(string.Join(';',Enumerable.Range(0,130).Select(x=>"milk "+x))+"; peanuts","en");Check(many.Findings.Any(x=>x.Item=="Yer fıstığı")&&many.Findings.Count<=16,"Finding limit hid a different allergen");
using var doc=JsonDocument.Parse("""{"product":{"code":"3017620422003","ingredients_text":"milk","lang":"en","allergens_tags":["en:milk"],"traces_tags":["en:peanuts"]}}""");
var product=OpenFoodFactsCatalog.Parse(doc.RootElement,"3017620422003",DateTimeOffset.UtcNow).Product!;Check(product.Allergens.SequenceEqual(["en:milk"])&&product.Traces.SequenceEqual(["en:peanuts"]),"OFF allergen/trace mapping");
var provider=new EphemeralDataProtectionProvider();var ctx=new DefaultHttpContext();var accessor=new HttpContextAccessor {HttpContext=ctx};var browser=new BrowserFoodPreferences(provider,accessor);browser.Write(ctx,P("milk"));var cookie=ctx.Response.Headers.SetCookie.ToString();Check(cookie.Contains("httponly",StringComparison.OrdinalIgnoreCase)&&cookie.Contains("samesite=strict",StringComparison.OrdinalIgnoreCase)&&!cookie.Contains("milk"),"Protected cookie flags/plaintext");
var next=new DefaultHttpContext();next.Request.Headers.Cookie=cookie.Split(';')[0];accessor.HttpContext=next;Check(browser.Read().Allergens.SequenceEqual(["milk"]),"Preference cookie read");
var tampered=new DefaultHttpContext();tampered.Request.Headers.Cookie=BrowserFoodPreferences.Cookie+"=tampered";accessor.HttpContext=tampered;Check(!browser.Read().Active,"Cookie tampering");
Console.WriteLine("PASS: 14 groups, limits, negation/trace/separate ingredients, TR/FR normalization, boundaries, unsupported language tags, vegan, lactose/milk separation, custom Unicode, complete warning groups, OFF mapping, protected cookie/tampering.");
